<?php require_once 'config.php'; if(logged_in())redirect('dashboard.php');$pageTitle='Log in';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$email=strtolower(trim($_POST['email']??''));$password=$_POST['password']??'';try{$s=db()->prepare('SELECT id,name,email,password,role,competencies FROM users WHERE email=? AND status="active" LIMIT 1');$s->execute([$email]);$u=$s->fetch();if($u&&password_verify($password,$u['password'])){session_regenerate_id(true);unset($u['password']);$_SESSION['user']=$u;flash('Welcome back, '. $u['name'].'!');redirect('dashboard.php');}$error='Email or password is incorrect.';}catch(Throwable $e){$error='Unable to connect to the database. Check setup instructions in README.md.';}}
